import java.util.ArrayList;
import java.util.List;

public class ArrayListGrowthDemo {
    public static void main(String[] args) {
        // Default constructor initializes with an empty array,
        // which expands to capacity 10 on the first element insertion.
        List<String> dynamicList = new ArrayList<>();

        // If the final size is known beforehand, always size explicitly
        // to bypass the internal 1.5x array allocation and copying churn:
        List<String> preSizedList = new ArrayList<>(10000);
    }
}
